#!/usr/bin/env python3
import argparse
import csv
import json
from datetime import date, datetime, time
from pathlib import Path

from openpyxl import load_workbook


def serialize_value(value):
    """Convert Excel values into readable, JSON-safe text."""
    if value is None:
        return ""
    if isinstance(value, (datetime, date, time)):
        return value.isoformat()
    return str(value)


def extract_workbook(source_path, output_path):
    source = Path(source_path).expanduser()
    output = Path(output_path).expanduser()

    if not source.is_file():
        raise FileNotFoundError(f"Workbook not found: {source}")

    # data_only=False preserves formulas rather than cached results.
    workbook = load_workbook(source, read_only=True, data_only=False)

    records = []
    sheet_summary = {}

    try:
        for worksheet in workbook.worksheets:
            populated_count = 0

            for row in worksheet.iter_rows():
                for cell in row:
                    if cell.value is None:
                        continue

                    records.append(
                        {
                            "worksheet": worksheet.title,
                            "coordinate": cell.coordinate,
                            "value": serialize_value(cell.value),
                            "data_type": cell.data_type,
                        }
                    )
                    populated_count += 1

            sheet_summary[worksheet.title] = populated_count
    finally:
        workbook.close()

    output.parent.mkdir(parents=True, exist_ok=True)

    if output.suffix.lower() == ".json":
        payload = {
            "source_workbook": str(source),
            "worksheet_count": len(sheet_summary),
            "populated_cell_count": len(records),
            "worksheets": sheet_summary,
            "cells": records,
        }
        output.write_text(
            json.dumps(payload, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )
    else:
        with output.open("w", newline="", encoding="utf-8-sig") as file:
            writer = csv.DictWriter(
                file,
                fieldnames=["worksheet", "coordinate", "value", "data_type"],
            )
            writer.writeheader()
            writer.writerows(records)

    print(f"Source: {source}")
    print(f"Output: {output}")
    print(f"Worksheets: {len(sheet_summary)}")
    print(f"Populated cells: {len(records)}")
    for sheet_name, count in sheet_summary.items():
        print(f"  {sheet_name}: {count}")


def main():
    parser = argparse.ArgumentParser(
        description=(
            "Extract every populated Excel cell while preserving worksheet "
            "names and cell coordinates."
        )
    )
    parser.add_argument("workbook", help="Path to the source .xlsx workbook")
    parser.add_argument(
        "-o",
        "--output",
        default="order_summary_cells.csv",
        help="Output .csv or .json path (default: order_summary_cells.csv)",
    )
    args = parser.parse_args()

    extract_workbook(args.workbook, args.output)


if __name__ == "__main__":
    main()

